P["DT-001"] = ("父病可愈（终局单一方向：愈）：用神父母子水虽春休、被未日土克，然五爻官鬼申金独发来生子水，鬼虽为病、动而生用，病有转机；近段病势缠绵，远段得金水引动而解。应期双层：窗口为出占后一旬内（日档，近病尺度），主坐标子日（逢值填实一路）；三路：冲实无空可冲不取、填实取子水逢值、逢合申子合水局助用同指子日。二路复推：逢值子日与申子合局同点，二路同点。对象复述：主断语主语为父（父母子水），与所问父病同一。",
"liuyao\n春辛未日雷水解：父母子水现于初爻为用（非伏，卡面 hidden_spirit 语与现爻并存，以现爻为主、伏语只作旁记）；官鬼申金动生用神。旺衰：子水春休囚得申金动生为有救。应期三步日档已走，门类对表：病占首选逢值/出空，本例无空取逢值。动化方向核对：申金→子水：生，成立。", 0.55, T(False, False, False, "用神父母现卦、官鬼动非用神本身，未定 changed_main；伏语旁记未作主用，未定 reserve_used；动爻读法无歧，未定 disputed。"))
P["DT-002"] = ("妻与胎俱安、可保（终局：安）：妻财酉金伏于世爻子孙戌土之下，飞来生伏得长生，伏神待出四项中伏得飞生、飞土不压两项成立，待出而有力；世爻子孙戌土为胎，得三爻兄弟午火动生，胎气有生；上爻父母寅木动秋囚无力克子孙。近段孕中惊扰，远段安产。应期双层：窗口至酉月/酉日金气值时（月档，孕产尺度），主坐标酉日（伏神逢值出伏一路）；三路：冲实取酉逢冲卯日与终局安向不合舍、填实无空舍、逢值酉值取中。二路复推：逢值酉与飞生伏出同指酉，二路同点。对象复述：妻（妻财酉）与胎（子孙戌）逐名对回。",
"liuyao\n秋壬午日山水蒙：妻财不上卦取伏神酉金（reserve），飞神戌土生伏；子孙戌土持世为胎，午火动生世。卡面明载动爻原文以飞伏语叙述、图解本整理有出入，动爻组读法存歧，已降置信并记 disputed。伏神待出判别：得飞生、飞不压成立，生伏动爻午生世不直接生伏、冲飞无，待出中档。", 0.50, T(False, True, True, "妻财伏藏取伏神作主用，reserve_used=true；用神本身未动，changed_main=false；卡面明载飞伏动爻读法与图解本整理分歧，disputed=true。"))
P["DT-003"] = ("出商之子安危不利、未归（终局：凶滞不归）：用神子孙申金居应爻静，夏月金囚死无气，二爻父母午火旺相独发克申金，消息爻动而克人，行人受病伤/阻困于外；父母动只主音信惊扰，不作归讯。近段无归象，远段亦无子孙出空逢值之救（静而受克、无动化），一段终局，远段无据不报其归期。应期双层：窗口为申月金气稍回之时（月档），主坐标申日（子孙逢值一路，仅作险情应期坐标非归期）；三路冲实/填实皆无空墓不立，逢值申值取中作应期。二路复推：逢值申与月建申气同点。对象复述：主语为出商之子（子孙申），同一。",
"liuyao\n夏癸卯日艮为山八纯：子孙申金应爻为用，夏囚死；父母午火动克用。决策序：用神休囚无气+动爻旺克，无原神金土动生，终局从凶。六冲/八纯主滞。应期月档（行人尺度），对表行人类取逢值。", 0.58, T(False, False, False, "父母动非用神，changed_main=false；子孙现卦，reserve_used=false；盘面无读法分歧，disputed=false。"))
P["DT-004"] = ("子病可愈（终局：愈）：用神子孙两现，取动者丑土为主用，秋月土相、丑动克世爻官鬼亥水，药动克病为吉；官鬼亥水虽亦发动，亥为病爻动而逢子孙丑土克制、又秋水休囚，病势被压。近段病反复，远段丑土填实/值日后药力全、病退。应期双层：窗口一旬内（日档），主坐标丑日（用神逢值一路）；三路：冲实丑未冲作次选舍（冲动药爻散力）、填实无空舍、逢值丑值取中。二路复推：逢值丑与丑克亥病爻同指丑日，二路同点。对象复述：主语为患病之子（子孙丑），同一。",
"liuyao\n秋庚寅日天火同人：子孙两现按候选枚举取动爻丑土，官鬼亥水为病。卡面明载动爻组三处并记、原文飞伏交错读法有歧，记 disputed 并降置信。用神动化方向：丑土→亥水：克，药克病成立。", 0.52, T(True, False, True, "主用神子孙丑土本身发动，changed_main=true；子孙现卦，reserve_used=false；卡面明载动爻读法有歧，disputed=true。"))
P["DT-005"] = ("子病可愈（终局：愈）：用神子孙亥水居应爻，冬月水旺当令，五爻兄弟酉金独发生亥水，原神有力生用；病爻官鬼午火冬囚、又受亥水克，病无根。近段即见转机，远段水旺之日全愈。应期双层：窗口数日内（日档），主坐标亥日（用神逢值一路）；三路：冲实亥巳冲为冲病亦候选、与逢值同指水气取逢值为主、填实无空舍、逢值亥值取中。二路复推：冲实巳日冲亥与逢值亥日异坐标，按闸门无空墓、以终局愈向取逢值亥日，复推留痕异点已裁。对象复述：主语为患病之子（子孙亥），同一。",
"liuyao\n冬甲戌日泽水困：子孙亥水旺相、兄弟酉金动生用，官鬼午火囚克。决策序旺衰日月俱扶用神，终局愈。应期日档病占对表取逢值。动化：酉金→亥水：生，成立。", 0.70, T(False, False, False, "兄弟动生用非用神本身，changed_main=false；子孙现卦，reserve_used=false；无读法分歧，disputed=false。"))
P["DT-006"] = ("子病重危（终局：凶、不治倾向）：用神子孙巳火伏于五爻父母子水之下，飞神子水克伏，伏神待出四项仅飞神为日辰卯木所泄一项旁及、伏得生扶无、动爻生伏无、冲飞无，待出不成立；且五爻父母子水发动直克伏火，春月火相而受旺水动克，药/子孙线被压。近段病进，远段无出伏之路，一段终局。应期双层：窗口为巳火值时之前一旬（日档），主坐标巳日（伏神逢值作危情应期，非愈期）；三路：冲飞子水取午日冲子为唯一救路候选、终局凶向不取作愈期只入 reasoning，填实无，逢值巳值取中作危点。二路复推同指危在巳值。对象复述：主语为患病之子（子孙巳伏），同一。",
"liuyao\n春癸卯日山风蛊：子孙巳火伏藏取伏神（reserve），飞神父母子水动克伏。伏神待出五步：飞旺克伏、伏无日月生扶（春火相而水动克），难出档。卡面动爻以飞伏语叙述、图解本整理蛊之鼎与原文有出入，记 disputed。", 0.56, T(False, True, True, "子孙伏藏取伏神，reserve_used=true；用神未动，changed_main=false；卡面飞伏动爻读法与图解本分歧，disputed=true。"))
P["DT-007"] = ("家宅不安、主财耗暗失（终局：不利）：四爻妻财酉金乘玄武独发，春月金囚，财动乘玄武主暗昧盗失、财物耗散；宅之父母寅木初爻春旺，宅基尚在，故量级止于耗财惊扰、不至败宅。酉金动化卯木（未济变爻酉化卯），化财回头受春木之气、财去之象。应期双层：窗口一月内（月档，家宅尺度），主坐标酉日（财爻逢值一路）；三路：冲实酉卯冲即化神值、与逢值同月取逢值，填实无空舍，逢合酉辰合次选舍（合住财爻）。二路复推：逢值酉与冲化神卯同指财动之期，取酉为主坐标。对象：应验对象为该宅财物（非人对象），不回收到宅主之身。",
"liuyao\n春正月戊戌日火水未济：妻财酉金玄武动为家宅主线，父母寅木旺为宅基。动化方向核对：酉金化卯木，金克木为财化子孙向、财散象。应期月档。", 0.55, T(False, False, False, "动爻为妻财、家宅主用父母未动，未定 changed_main（化出卯木只作财散象留痕）；无伏神取用，reserve_used=false；无读法分歧，disputed=false。"))
P["LR-001"] = ("有惊无险、平安生还（终局：生还获释）：所问为被扣元首之生死，断其性命无虞，扣押终以谈判方式解开，本人于事变当月内获释南归；应期尺度日/旬档：窗口为事变起两旬内，主坐标在事变后约两周之日（旬内后段，定值粒度降为旬窗，因无盘不定单日）。置信低：卡面无课式、三传、四课、干支占时，六壬程序无从执行，此断只按题面已载面（元首被扣、外界忧其性命）给方向与旬窗，盘面细断一概无据不报。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决按六壬/占卜通例方向断。输入残损严重：卡面未载占时干支、月将、四课、三传、天将、年命任何盘面字段，九宗取传与分类占断程序无从执行，已降置信至 0.30 并在断语明写无据不报细断，不臆补盘面。已载面：主问面蒋氏生死、关系面扣押方，已断；盘面细面无据不报。", 0.30, T())
P["LR2-013"] = ("回奏有利、参劾不伤其位（终局：吉）：重审课先迷后利，铸印格主印绶迁拜；三传巳火（丁日同类、天空）→戌土（食伤/子孙向、螣蛇）→卯木太常（父母印绶生日干）收束，末传印绶乘太常临干生身，回奏得上意回护。近段参劾惊扰，远段以卯印定案无罪/轻结。应期月档：窗口至卯木值时，主坐标卯日（末传逢值一路；六壬三路：逢值卯取中、逢冲酉冲卯与终局吉向悖舍、出空申酉空与本案无空传舍）。章奏门类神朱雀不入传，文书面降一档作次线：回奏文书终达。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：癸酉年二月丁丑日丙午时，课式重审铸印，三传巳天空戌螣蛇卯太常，旬空申酉（落空丑寅不作空亡，遵单口径）。取用层：父母卯印为主面（一级入传临末乘太常），朱雀文书面不入传降二级。", 0.60, T())
P["LR2-014"] = ("狱中人凶中有救、终得脱罪轻结（终局：脱）：重审玄胎，三传申金六合（丙日妻财）→亥水贵人（官鬼乘贵人生日干之恩面）→寅木玄武（父母印生日、化鬼生身）收束；官鬼亥乘天乙贵人且得寅印转化，公讼门父母化官、贵人恩星之象叠见，主遇恩开豁。近段仍囚系，远段寅亥合处脱幅。应期月档：主坐标寅日（末传逢值兼亥寅合一路；三路：逢值寅取中、逢冲申冲寅已在初传不作末应舍、出空子丑空无空传舍）。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：辛未年四月丙辰日甲午时，课式重审玄胎，三传申六合亥贵人寅玄武，旬空子丑（卯辰落空不作空）。公讼取用：官鬼亥为主面、乘贵人且末传寅印化鬼，赦路按遇赦识别第4条恩星面读，单独不作全释、与化官叠见方强断脱。", 0.58, T())
P["LR2-015"] = ("重罪难赦、出狱无望（终局：凶、罪不脱）：乙未日三传午火天空（食伤、虚诈）→丑土天后（妻财）→申金勾陈（官鬼克乙日干、乘勾陈主词讼稽留）收束，末传鬼克日且勾陈临末，刑部已定重辟之势无恩星、赦神入传生日（太岁丙子、贵人线无生日据），赦路无据。近段逮系，远段申金值时罪定执行之险最重。应期月档：主坐标申日（末传鬼逢值一路；三路：逢值申取中、逢冲寅冲申与罪定方向悖舍、出空辰巳空无空传舍）。置信中上。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：丙子年三月乙未日己卯时，重审，三传午天空丑天后申勾陈，旬空辰巳（亥子落空不作空）。公讼遇赦逐象核：皇恩天赦恩星均无入传生日据，赦路不成立；末传官鬼勾陈克日为一级主据定凶。", 0.64, T())
P["LR2-016"] = ("出狱有望但迟、同难所言指日即出不准（终局：迟出）：己酉日三传亥水螣蛇（妻财、惊扰）→午火天空（父母印生日干）→丑土天后（同类、支体）收束，印午中传生日为脱路线索，末传丑为日支同气、狱体得归；然初传亥乘螣蛇主缠扰、午乘天空虚诈，速出之说落空。应期月档：窗口跨两月，主坐标丑日（末传逢值兼丑未冲开之路；三路：逢值丑取中、逢冲未冲丑同指丑位合流、 出空寅卯空无空传舍）。二路复推：逢值与逢冲同指丑，二路同点。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：丙子年三月己酉日丁卯时，蓦越重审，三传亥螣蛇午天空丑天后，旬空寅卯（酉戌落空不作空）。行人/公讼合参：印生日为救、末传归支定迟出；天空乘印降速断置信。", 0.56, T())
P["LR2-017"] = ("与冯允升同课同断：重罪难全释（终局：凶、久系难脱）：乙未日三传午天空→丑天后→申勾陈，末传申金官鬼克日乘勾陈，定罪八载仍无赦象入传（皇恩天赦恩星俱无生日据），久系之体不因年久而转。近段仍无出讯，远段申金值时为罪体再定之期。应期月档：主坐标申日（末传逢值一路；三路同 LR2-015 口径：逢冲舍、出空无据舍）。同盘异人年命未给，年命面无据不报，故主断与同课例一致。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：丙子年二月乙未日己卯时，重审，三传与 LR2-015 全同（卡面明载与冯允升课同），旬空辰巳。无年命字段，个体差异面无据不报，主线按同盘同断。", 0.58, T())
P["LR2-018"] = ("免死减等、罪重还轻逐（终局：保命不全释）：乙酉日涉害天狱课体凶，三传未土青龙（妻财、初传逢午未旬空为空）→子水贵人（父母印生日干、乘天乙）→巳火白虎（食伤制鬼向）收束；贵人子水生日即公讼恩星面，罪虽重还轻逐，主死罪减等、谪戍/久系而非全释。应期月档：主坐标巳日（末传逢值一路；三路：逢值巳取中、逢冲亥冲巳次选舍（冲动食伤散力）、出空初传未空待未值作次线舍）。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：丙子年二月乙酉日辛巳时，涉害天狱，三传未青龙子贵人巳白虎，旬空午未（初传未空斩首象只降权）。遇赦识别：太岁/贵人作恩星（子水贵人生乙日）一象成立，程度按第11条分档作减等不作全释。", 0.57, T())
P["LR2-019"] = ("勤王此行吉、将士可建功而还（终局：吉）：辛酉日重审进茹，三传酉金朱雀（同类、干旺）→丑土太阴（父母印生日干）→巳火天空（官鬼、乘天空虚而不实）收束，日干金旺得印生，末传鬼虚无力克身；进茹顺进主行程推进。近段进发顺，远段巳火虚惊一场而无大败。应期月档：主坐标丑日（中传印逢值一路；三路：逢值丑取中、逢冲未冲丑舍、逢合巳酉丑金局合流同指金旺取丑为印坐标）。置信中上。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：乙酉年四月辛酉日丙申时，重审进茹，三传酉朱雀丑太阴巳天空，旬空子丑（丑为落空组？卡面作丑寅落空，丑本身非旬空，按单口径不作空亡）。兵斗门干为攻方旺相印生定吉。", 0.62, T())
P["LR2-020"] = ("携妻远行不利、宜止不行（终局：止/凶）：庚申日八专课干支同体、绝嗣凶格，三传戌土六合（印）→巳火太常（官鬼克庚）→子水螣蛇（食伤、惊扰）收束，行程中段巳鬼克干、末传子螣蛇主途中惊扰，妻行面以六合戌印初传只作同行面、无吉将生扶。已行则中途折返。应期月档：主坐标巳日（鬼爻逢值作阻应一路；三路：逢值巳取中、逢冲亥冲巳与止行方向同向作次选舍、逢合巳申合绊同指不行舍作主坐标）。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：庚寅年五月庚申日丁丑时，八专绝嗣，三传戌六合巳太常子螣蛇，卡面未另列空亡。出行门：八专总象帷簿不修同体不分、绝嗣凶格，鬼克干居中传定止。", 0.60, T())
P["LR2-021"] = ("女儿平安到京（终局：到）：壬戌日元首玄胎，三传巳火贵人（妻财/行人面乘贵人）→寅木六合（食伤、驿马寅入传乘六合）→亥水天空（同类归源）收束，驿马入传、末传亥为壬禄归处，行人门末传抵归之象。应期日档（近程行人）：窗口数日内，主坐标寅日（驿马逢值一路；三路：逢值寅取中、逢冲申冲寅舍、逢合寅亥合末传合流同指归途取寅为马坐标）。二路复推：逢值寅与寅亥合同点于归，二路同点。途安面：巳贵人初传主途中有贵助，平安。置信中上。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：戊辰年十一月壬戌日乙巳时，元首玄胎，三传巳贵人寅六合亥天空，旬空子丑（酉戌落空不作空）。行人门取驿马（申子辰局外此盘以寅为壬日马星入传）与末传亥归源定到。", 0.62, T())
P["LR2-022"] = ("弟病可愈（终局：愈）：丁亥日重审铸印，三传巳火天空（同类）→戌土螣蛇（食伤泄病气）→卯木太常（父母印生日干、乘太常主医药衣食之养）收束，末传印生身、铸印主祯祥，病源官鬼水不入三传（只降权不作无病，然生克链无鬼克身据）。近段巳戌段病势反复，远段卯印值时痊愈。应期日档：窗口一旬内，主坐标卯日（末传逢值一路；三路：逢值卯取中、逢冲酉冲卯舍、逢合卯戌合中传合流取卯）。对象：主语为弟观初（以丁日干线及印生线对回），同一。置信中上。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：辛巳年九月丁亥日辛丑时，重审铸印，三传巳天空戌螣蛇卯太常，旬空午未（亥子落空不作空）。疾病门：官鬼不入传按 LR-QY-2 只降权，印生末传为一级据定愈。", 0.62, T())
P["LR2-023"] = ("病可愈、虚惊为主（终局：愈）：己酉日蒿矢三交，三传卯木玄武（官鬼、逢寅卯旬空为初传空）→午火天空（父母印生日干）→酉金六合（食伤制鬼向）收束，病鬼初传空亡主病源虚浮待实而力弱，印午生身、末传食伤制鬼，愈向成立；三交主家事阴私牵连为次线（席间家事面，只作背景不压主断）。应期日档：窗口一旬内，主坐标午日（印爻逢值一路；三路：逢值午取中、冲实卯待子冲与愈向不合舍、出空卯出空作病应次线舍）。对象：主语张澹宁本人，同一。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：己卯年六月己酉日戊辰时，蒿矢三交，三传卯玄武午天空酉六合，旬空寅卯（初传卯空）。疾病门致死象组逐项无叠见，鬼空+印生+食制三据定愈；三交次面按 LR-QY-1 降次线。", 0.60, T())
P["LR2-024"] = ("病可愈（终局：愈）：己亥日重审交车，三传午火天空（父母印生日干）→丑土天后（同类）→申金勾陈（食伤泄秀制鬼向）收束，印生身居初、病源官鬼水不入传，己土得午印之生而稳；勾陈末传主病程稽留，愈而迟。应期日档：窗口一旬余，主坐标午日（印爻逢值一路；三路：逢值午取中、逢冲子冲午舍、逢合午未合次选舍）。对象：主语卢承山本人，同一。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：乙酉年正月己亥日己巳时，重审交车，三传午天空丑天后申勾陈，旬空辰巳（亥子落空不作空）。疾病门印生为一级据；勾陈稽留只调量级作迟愈。", 0.58, T())
assert set(IDS_B05) <= set(P) and len([k for k in IDS_B05 if k in P]) == 20, "B05 full set mismatch"
