P["LR3-107"] = ("来客为涉讼阴私、不实之人，吉凶偏凶须防（终局：凶客）：甲午日三传子水天后（父母印、阴面）→亥水太阴（父母印、蔽匿）→戌土玄武（妻财乘玄武、盗诈面）收束，水印两重主其人藏头露尾、太阴天后主阴私，末传玄武财主暗昧牵连；课出公讼门，来客身份定为与讼事/囚系牵连或行藏不实之人，非清白显达之客。应期日档：主坐标亥日（太阴逢值作应候一路；三路：逢值亥取中、逢冲巳冲亥舍、逢合亥寅合无寅舍）。课式首字残泐存疑，已降置信。置信中下。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：壬午年七月甲午日庚午时，课式退茹（卡面注原书课体首字残泐存疑），三传子天后亥太阴戌玄武，旬空辰巳（卯辰落空不作空）。射覆/身份占以将乘类象定面：太阴天后玄武三将叠阴，身份面一级据；残泐面降置信。", 0.50, T())
P["LR3-110"] = ("失马可寻回（终局：得）：癸卯日知一斫轮，三传卯木朱雀（食伤、消息面）→戌土白虎（官鬼、道路白虎面）→巳火贵人（妻财、马体归贵人面）收束，失物以妻财为本体，财巳居末乘贵人不空（辰巳为空亡组？癸卯属甲午旬辰巳空——巳为旬空，财空待出空填实而得，不作已失断）；寻方以末传巳位定东南巳方。应期日档：窗口至巳火出空填实，主坐标巳日（财爻填实一路；三路：填实巳取中、冲实巳亥冲次选舍、逢值同巳合流）。二路复推填实与逢值同指巳。置信中。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：庚寅年十月癸卯日庚申时，知一斫轮，三传卯朱雀戌白虎巳贵人，旬空辰巳（末传巳旬空）。失物门财空按第三节空亡非终局凶判、出空填实为应期，方所据玄武阴神未给降一档以末传位定方。", 0.55, T())
P["LR3-112"] = ("病可愈（终局：愈）：戊申日元首润下，三传辰土玄武（同类）→申金青龙（食伤制鬼、乘青龙喜庆）→子水螣蛇（妻财）收束，申子辰润下水局主病在痰饮水湿，官鬼木不入传，食伤申金居中制鬼向、青龙吉将，愈向成立；水局末传子螣蛇主愈后仍有惊扰余波。应期日档：主坐标申日（食爻逢值一路；三路：逢值申取中、逢冲寅冲申舍、逢合申子辰局合流同指申）。对象：主语刘一纯本人，同一。置信中上。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：辛未年正月戊申日己未时，元首润下，三传辰玄武申青龙子螣蛇，旬空寅卯（午未落空不作空）。疾病门鬼不入传只降权，食制青龙一级据定愈。", 0.62, T())
P["LR3-114"] = ("鸦鸣主虚惊与暗失之兆、无大灾（终局：小凶无大害）：乙丑日重审退茹，三传子水太常（父母印）→亥水玄武（父母印乘玄武、阴私盗面）→戌土太阴（妻财、暗昧）收束，夜鸣应候以玄武亥居中为眼：主近有阴私/盗失消息或夜客虚惊，财戌太阴主财物暗耗一线，不至人身大凶。应期日档：窗口数夜内，主坐标亥日（玄武逢值一路；三路：逢值亥取中、逢冲巳冲亥舍、逢合亥寅合无寅舍）。置信中下（应候占证据粒度弱，断项已降为倾向级）。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬：己丑年三月乙丑日丁亥时，重审退茹，三传子太常亥玄武戌太阴，旬空戌亥（末传戌旬空、亥为落空组所临非空）。应候门无专属类神，以乘玄武之传为眼，断项粒度按 R61-REV1-4 仅 1 指针者降倾向。", 0.48, T())
P["LR3-116"] = ("射覆：袖中所包为柔软阴性之物——折叠的巾帕/布帛类（或同类纸帛折叠物），色暗、体积小可握。甲寅日八专，三传丑土贵人（妻财、贵重面）→亥水太阴（父母/阴柔蔽匿面）→亥水太阴重叠，太阴两重主阴柔蔽匿之物贴身藏，丑土为其外裹/质地偏土黄。断项粒度：具体物名只有太阴阴柔一类指针成链、丑亥质地为第二指针，保留至『巾帕布帛类折叠物』类级，不硬指单件名目。置信低。三传天干未载、旬空未载，属输入残损，已注明降置信。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决大六壬射覆：辛巳年八月甲寅日壬申时，八专，三传丑贵人亥太阴亥太阴；卡面明载三传天干未载、原书未载旬空，属残损。射覆以将乘类象定物类，太阴重叠为阴柔物一级象，物名按粒度收束降至类级。", 0.40, T())
P["LY-001"] = ("将来有官（终局：有官）：前后两卦合断——初占官鬼巳火动而亥月月破，破不作无官断（月破章本旨：得验者应乎月破），巳官动化寅、待出月填实而起；再占水地比静卦，官鬼卯木持世、亥月木得月生旺，官星临世有根，两卦同指官位可得而应在后。应期双层：窗口为出亥月后木火值时（月档，仕途尺度），主坐标寅月（初官化神逢值一路；三路：填实巳破待填作次选舍（尺度在月取寅先于巳日）、逢值寅取中、冲实巳亥冲已在占月舍）。置信中上。动化核对：巳火化寅木，木生火回头生，官得生扶。",
"liuyao\n亥月己丑日：初占兑为泽初爻官鬼巳火、五爻父母未土动；再占比卦官鬼卯木世。用神候选枚举：初卦官巳（月破标记，保留应验位）、再卦官卯（旺相无标记）为主用，两卦合断主用取卯、应验位留巳。月破按候选裁决第3步不径舍。", 0.64, T(True, False, False, "初卦用神官鬼巳火本身发动，changed_main=true；官现卦，reserve_used=false；两卦合断为卡面明载占法非读法分歧，disputed=false。"))
P["LY-002"] = ("父即归（终局：归）：用神父母戌土居上爻发动，辰月土旺、戌得月冲而动（冲动非冲散，戌土旺相有气判暗动之上更兼明动），动化未土同类，父已在途、归意已决；世爻即父母本爻，归期近。应期双层：窗口数日内（日档，行人近归尺度），主坐标戌日（用神逢值一路）；三路：逢值戌取中、冲实辰冲戌已发动不另取、填实无空舍。二路复推：逢值戌与化神未逢合（戌未同土）同指近归，取戌为主坐标。对象复述：主语为父（父母戌），同一。",
"卡面未标注 tradition 字段，按题面体裁自决\n自决六爻：辰月戊子日乾为天之夬，上爻父母戌土动化未。用神父母现卦旺相发动，决策序旺衰有气，动不为空类推归近。应期日档行人门对表取逢值。", 0.66, T(True, False, False, "用神父母戌土本身发动化未，changed_main=true；父母现卦，reserve_used=false；无读法分歧，disputed=false。"))
P["LY-003"] = ("子病重危（终局：凶）：用神子孙午火伏于世爻妻财丑土之下，酉月火囚、辰日土旺泄火，飞神丑土泄伏而非生伏，伏神待出四项：伏得日月生扶无（酉月辰日皆不生火）、飞神空破墓绝无、动爻生伏无（静卦）、冲飞无，四项俱无待出不成立；卦中官鬼酉金两现旺相为病势张。近段病进，远段无出伏救路，一段终局。应期双层：窗口一旬内（日档），主坐标午日（伏神逢值作危点一路；三路：逢值午取中作危应、冲飞丑取未冲作唯一救路候选终局凶向不取作愈期、填实无空舍）。对象复述：主语为患病子女（子孙午伏），同一。",
"liuyao\n酉月丙辰日地风升静卦，子孙午火伏藏取伏神（reserve）。伏神待出五步清单逐项核毕四项俱无、根基两项俱缺，难出档；官鬼酉旺为病。病占原神即子孙线本身衰伏，按决策序第7步凶断条件近齐降一格作重危。", 0.58, T(False, True, False, "子孙伏藏取伏神，reserve_used=true；静卦用神未动，changed_main=false；盘面无分歧，disputed=false。"))
P["LY-004"] = ("父病大凶、危在近段（终局：凶、不治倾向）：四卦合断同指一线——复卦父母巳火伏官鬼寅木下木生火待拨，损卦父母巳火现初爻，渐卦父母午火动化妻财亥水回头克，卯月火相得生而化神亥水辰日克火，用神动而化克为病进之据；多占同卦同断，病势甚危（卡面载医者满座、势甚危与盘面合）。应期双层：窗口一旬内（日档），主坐标午日（动用神逢值作危点一路；三路：逢值午取中、冲实午子冲次选舍、填实巳伏待巳日作次线舍）。对象复述：四卦主语皆为父（父母巳/午），逐名对回同一。量级：多卦叠证作重危至不治倾向，不直断必死之日。",
"liuyao\n卯月丙辰日四占合参：父母伏、现、动化克三态并见，主用取渐卦动爻父母午火，化亥水回头克（动化方向核对：亥水→午火：克，成立）。伏神巳火在复卦作应验位留置（reserve 参与合断）。应期日档病占取逢值。", 0.62, T(True, True, False, "渐卦用神父母午火动化回头克，changed_main=true；复卦父母伏藏参与合断留应验位，reserve_used=true；四卦为卡面明载合占法非读法歧，disputed=false。"))
P["LY-005"] = ("乡试可中（终局：中）：用神官鬼申金居五爻发动，申月金旺临月，动化酉金进神，官星旺相化进主名位前进；父母亥水为文书卷，现卦旺于申月金生，官动生父（卷）链通。应期双层：窗口为放榜季内（月档，考试尺度），主坐标酉月（化神逢值一路；三路：逢值酉取中、填实无空舍、冲实申寅冲次选舍（冲动官爻散力））。二路复推：化进酉值与官生文书同指酉，二路同点。动化核对：申金化酉金同类进神，生父母亥水成立。",
"liuyao\n申月癸卯日雷风恒之大过，五爻官鬼申金动化酉。用神官鬼旺相化进，决策序化进证据链：化神得月建同气、非空破，进成立。乡试门类取官+父母双线。", 0.66, T(True, False, False, "用神官鬼申金本身动化进神，changed_main=true；官现卦，reserve_used=false；无分歧，disputed=false。"))
P["LY-006"] = ("求婚可成而迟、多番周折后成（终局：成）：用神妻财未土持世发动，卯月木旺克土、乙丑日土帮，世财动化戌土同类帮身，财临世主动可成；然四爻俱动——官鬼酉金动化申退、父母子水动化未财、上爻子孙巳火动化子水，动多主事乱，先阻后通。应期双层：窗口一月内（月档），主坐标戌日（世财化神逢值一路；三路：逢值戌取中、冲实未丑冲已在日辰作已动舍、填实无空舍）。对象：妻财未即所求婚对象面，同一。置信中下：动多降一档。",
"liuyao\n卯月乙丑日山火贲之比：妻财未土世动化戌为用，月克日帮旺衰参半；四动乱局按动化逐爻核：酉化申退、子化未、巳化子。终局按（l）单判取成，迟与周折入过程。", 0.52, T(True, False, False, "用神妻财未土持世发动，changed_main=true；财现卦，reserve_used=false；卦名由装卦推得为卡面明示非分歧，disputed=false。"))
